                method: "obtener_licencias_conductor",
                args: { docname: frm.doc.conductor},
                callback: function(r) {
                    if (r.message) {
                            frm.fields_dict.licencia_conductor.df.options = r.message;
                            frm.refresh_field("licencia_conductor");
                        }

                }
            });
	    }

	    if(frm.doc.el_conductor_es_de_la_empresa =="Sí")
	    {
            frappe.call({
                method: "obtener_vehiculos_asignados",
                args: { empleado: frm.doc.empleado_conductor },
                callback: function (response) {
                    console.log("ve1h", response)
                    if (Array.isArray(response.message)) {
                        let vehiculos = response.message.map(obj => obj.parent);
                        console.log("veh", vehiculos)
                        frm.set_query('vehículo', () => {
                            return {
                                filters: {
                                    name: ['in', vehiculos]
                                }
                            };
                        });
