                        //frm.set_value("vehículo", null);
                        // 👇 Filtro imposible para que no aparezca ningún resultado
                        frm.set_query('vehículo', () => {
                            return {
                                filters: {
                                    name: ['in', ['']]
                                }
                            };
                        });
                    }
                }
            });
