function calcular_puntos(frm) {
    console.log("ENTRO");

    let distancia = frm.doc.distancia_por_recorrer;
    let clima = frm.doc.clima;
    let condiciones = frm.doc.condiciones_de_la_via;
    let comunicaciones = frm.doc.comunicaciones_disponibles;
    let riesgo_seguridad = frm.doc.riesgo_seguridad_física;
    let vehículos_y_personas = frm.doc.vehículos_y_personas;

    let horaTraslado = frm.doc.hora_del_traslado;
    let horaTrabajadas = frm.doc.hrs_trabajadas_tiempo_de_viaje;

    let puntos_distancia = 0;
    let puntos_clima = 0;
    let puntos_condiciones = 0;
    let puntos_comunicaciones = 0;
    let puntos_seguridad = 0;
    let puntos_vehiculos = 0;
    let puntos_horaTraslado = 0;
    let puntos_horaTrabajadas = 0;

    // Distancia
    switch (distancia) {
        case "Menos de 50KM":
            puntos_distancia = 1;
            break;
        case "Menos de 100KM":
            puntos_distancia = 2;
            break;
        case "Menos de 200KM":
            puntos_distancia = 6;
            break;
        case "Mas de 200KM":
            puntos_distancia = 8;
            break;
        default:
            puntos_distancia = 0;
    }

    // Clima
    switch (clima) {
        case "Seco/ Condiciones Normales":
            puntos_clima = 2;
            break;
        case "Lluvia Suave":
            puntos_clima = 4;
            break;
        case "Lluvia Fuerte y/o Niebla":
            puntos_clima = 8;
            break;
        case "Nieve":
            puntos_clima = 10;
            break;
        default:
            puntos_clima = 0;
    }

    // Condiciones de la vía
    switch (condiciones) {
        case "Pavimentada":
            puntos_condiciones = 1;
            break;
        case "<50% No Pavimentada":
            puntos_condiciones = 2;
            break;
        case "No Pavimentada":
            puntos_condiciones = 4;
            break;
        default:
            puntos_condiciones = 0;
    }

    // Comunicaciones
    switch (comunicaciones) {
        case "Teléfono Celular":
            puntos_comunicaciones = 0;
            break;
        case "Sin Comunicación y En Caravana":
            puntos_comunicaciones = 2;
            break;
        case "Sin Comunicación y Sin Caravana":
            puntos_comunicaciones = 4;
            break;
        default:
            puntos_comunicaciones = 0;
    }

    // Riesgo Seguridad Física
    switch (riesgo_seguridad) {
        case "Bajo":
            puntos_seguridad = 1;
            break;
        case "Medio":
            puntos_seguridad = 5;
            break;
        case "Alto":
            puntos_seguridad = 10;
            break;
        default:
            puntos_seguridad = 0;
    }

    if(!frm.doc.es_caravana){
        switch (vehículos_y_personas) {
            case "Caravana":
                puntos_vehiculos = 1;
                break;
            case "1Vehi. Con 2 o + Personas":
                puntos_vehiculos = 3;
                break;
            case "1Vehi. Con 1 Persona":
                puntos_vehiculos = 6;
                break;
            default:
                puntos_vehiculos = 0;
        }
    }else{
        puntos_vehiculos= 1;
    }

    switch (horaTraslado) {
        case "Diurno (6:00h-18:00 Hrs.)":
            puntos_horaTraslado = 1;
            break;
        case "Nocturno (18:00-6:00 Hrs.)":
            puntos_horaTraslado = 5;
            break;
        default:
            puntos_seguridad = 0;
    }

    // Riesgo Seguridad Física
    switch (horaTrabajadas) {
        case "Hrs. Trabajadas + Tiempo de Viaje < 12":
            puntos_horaTrabajadas = 1;
            break;
        case "Hrs. Trabajadas + Tiempo de Viaje < 14":
            puntos_horaTrabajadas = 3;
            break;
        case "Hrs. Trabajadas + Tiempo de Viaje < 19":
            puntos_horaTrabajadas = 6;
            break;
        default:
            puntos_horaTrabajadas = 0;
    }

    let total = puntos_distancia + puntos_clima + puntos_condiciones + puntos_comunicaciones + puntos_seguridad + puntos_vehiculos + puntos_horaTraslado + puntos_horaTrabajadas;
/*
    console.log("Distancia:", puntos_distancia);
    console.log("Clima:", puntos_clima);
    console.log("Condiciones:", puntos_condiciones);
    console.log("Comunicaciones:", puntos_comunicaciones);
    console.log("Seguridad:", puntos_seguridad);
    console.log("Total:", total);*/

    if (total > 0 && total <= 19) {
        frm.set_value('riesgo', "Bajo");
    }
    if (total >= 20 && total <= 25) {
        frm.set_value('riesgo', "Medio");
    }
    if (total > 25) {
        frm.set_value('riesgo', "Alto");
    }

    frm.set_value('riesgo_en_puntos', total);
    frm.trigger('estilizar_riesgo');
}


