function calcular_tiempo_viaje(frm) {

    // Convierte HH:MM:SS a segundos
    function tiempoASegundos(tiempo) {
        if (!tiempo) return 0;

        let partes = tiempo.split(':').map(Number);

        let horas = partes[0] || 0;
        let minutos = partes[1] || 0;
        let segundos = partes[2] || 0;

        return (horas * 3600) + (minutos * 60) + segundos;
    }

    // Convierte segundos a HH:MM:SS
    function segundosATiempo(segundos) {

        let horas = Math.floor(segundos / 3600);
        let minutos = Math.floor((segundos % 3600) / 60);
        let secs = segundos % 60;

        return [
            String(horas).padStart(2, '0'),
            String(minutos).padStart(2, '0'),
            String(secs).padStart(2, '0')
        ].join(':');
    }

    let totalSegundos = 0;

    // Tiempo principal
    totalSegundos += tiempoASegundos(frm.doc.tiempo_de_la_ruta);

    // Tabla hija
    (frm.doc.puntos || []).forEach(row => {
        totalSegundos += tiempoASegundos(row.tiempo);
    });

    // Resultado
    let tiempoTotal = segundosATiempo(totalSegundos);

    // Asignar al campo destino
    frm.set_value('tiempo_de_viaje', tiempoTotal);

    //frappe.msgprint(`Tiempo total: ${tiempoTotal}`);
}

function calcular_fecha_hora_llegada(frm) {

    if (!frm.doc.fechahora_inicio_del_viaje) {
        return;
    }

    // Fecha inicial
    let fecha = new Date(frm.doc.fechahora_inicio_del_viaje.replace(' ', 'T'));

    let totalHoras = 0;
    let totalMinutos = 0;
    let totalSegundos = 0;

    // =========================
    // Tiempo de la ruta
    // =========================
    if (frm.doc.tiempo_de_la_ruta) {

        let tiempoRuta = frm.doc.tiempo_de_la_ruta.split(':');

        totalHoras += parseInt(tiempoRuta[0], 10) || 0;
        totalMinutos += parseInt(tiempoRuta[1], 10) || 0;
        totalSegundos += parseInt(tiempoRuta[2], 10) || 0;
    }

    // =========================
    // Tabla de puntos
    // =========================
    (frm.doc.puntos || []).forEach(row => {

        if (row.tiempo) {

            let tiempo = row.tiempo.split(':');

            totalHoras += parseInt(tiempo[0], 10) || 0;
            totalMinutos += parseInt(tiempo[1], 10) || 0;
            totalSegundos += parseInt(tiempo[2], 10) || 0;
        }
    });

    // =========================
    // Sumar a la fecha
    // =========================
    fecha.setHours(fecha.getHours() + totalHoras);
    fecha.setMinutes(fecha.getMinutes() + totalMinutos);
    fecha.setSeconds(fecha.getSeconds() + totalSegundos);

    // Formatear fecha
    let yyyy = fecha.getFullYear();
    let mm = String(fecha.getMonth() + 1).padStart(2, '0');
    let dd = String(fecha.getDate()).padStart(2, '0');

    let hh = String(fecha.getHours()).padStart(2, '0');
    let mi = String(fecha.getMinutes()).padStart(2, '0');
    let ss = String(fecha.getSeconds()).padStart(2, '0');

    let fechaFinal = `${yyyy}-${mm}-${dd} ${hh}:${mi}:${ss}`;

    // Asignar resultado
    frm.set_value('fechahora_de_llegada', fechaFinal);

    console.log("aa",hh)

    if (hh >= 6 && hh < 18) {
        frm.set_value('hora_del_traslado', "Diurno (6:00h-18:00 Hrs.)");
    } else {
        frm.set_value('hora_del_traslado', "Nocturno (18:00-6:00 Hrs.)");
    }

    calcular_puntos(frm)
}


